package dev.wowforever.importer.acquisition;
import static org.assertj.core.api.Assertions.*;
import com.sun.net.httpserver.HttpServer;import dev.wowforever.importer.setup.*;import java.io.*;import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
class BootstrapAcquisitionTest {
 @TempDir Path temporary;HttpServer server;AtomicInteger requests=new AtomicInteger();byte[] body="authored schema fixture".getBytes(StandardCharsets.UTF_8);int status=200;
 @BeforeEach void start()throws Exception{server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/schema",e->{requests.incrementAndGet();e.sendResponseHeaders(status,body.length);try(var out=e.getResponseBody()){out.write(body);}});server.start();}
 @AfterEach void stop(){server.stop(0);}
 SetupPlan.JobContext job(String id)throws Exception{var sources=Set.of(SetupPlan.Source.QUESTIE);return new SetupPlan(sources,Set.of(),Optional.empty(),List.of(),SetupPlan.currentPins(sources)).prepareJob(temporary.resolve("app"),Optional.empty(),id,List.of());}
 PinnedItemSparseDefinitionMaterializer reader(String hash,Duration timeout){return new PinnedItemSparseDefinitionMaterializer(URI.create("http://127.0.0.1:"+server.getAddress().getPort()+"/schema"),HttpClient.newBuilder().followRedirects(HttpClient.Redirect.NEVER).build(),timeout,hash,bytes->{if(!new String(bytes,StandardCharsets.UTF_8).equals("authored schema fixture"))throw new IOException("Invalid authored definition");});}
 PinnedItemSparseDefinitionMaterializer reader(){return reader(PinnedItemSparseDefinition.hash("authored schema fixture".getBytes(StandardCharsets.UTF_8)),Duration.ofSeconds(2));}
 PinnedItemSparseDefinitionMaterializer.Result run(SetupPlan.JobContext j)throws Exception{return reader().materialize(RaidbotsHotfixMaterializer.Permission.ALLOW_RAIDBOTS_HOTFIX,j,()->false,p->{});}
 @Test void productionBootstrapPresetHasReviewed51HashesAndExactForeverIdentity(){var manifest=Forever70450Bootstrap.wagoManifest();assertThat(manifest.tableSha256()).hasSize(51).containsKeys("ItemSparse","Item","Spell","AreaTable","DungeonEncounter");assertThat(manifest.identity()).isEqualTo(new SetupPlan.NativeIdentity("wow_classic_beta","1.60.1.70450","enUS"));assertThat(manifest.tableSha256().keySet()).noneMatch(name->name.contains("era")||name.contains("hotfix"));assertThatThrownBy(()->manifest.tableSha256().clear()).isInstanceOf(UnsupportedOperationException.class);}
 @Test void consentPrecedesWritesOrNetwork()throws Exception{var j=job("denied");assertThatThrownBy(()->reader().materialize(RaidbotsHotfixMaterializer.Permission.DENIED,j,()->false,p->{})).hasMessageContaining("not selected");assertThat(requests).hasValue(0);assertThat(j.paths().cache().resolve("itemsparse-definition")).doesNotExist();}
 @Test void verifiedSchemaAndProofReuseNeedsZeroNetwork()throws Exception{var j=job("reuse");var initial=run(j);var reused=reader().materialize(RaidbotsHotfixMaterializer.Permission.ALLOW_RAIDBOTS_HOTFIX,j,()->false,p->{throw new AssertionError("network reuse");});assertThat(reused.reused()).isTrue();assertThat(reused.definition()).isEqualTo(initial.definition());assertThat(Files.readString(reused.evidence())).contains("provider=WOWDBDEFS_SCHEMA","gameDataPayload=false");assertThat(requests).hasValue(1);}
 @Test void malformedCachedMetadataIsRecoveredByFreshVerifiedAcquisition()throws Exception{var j=job("malformed");var first=run(j);Files.writeString(first.evidence(),"broken=\\uNOPE\n");var second=run(j);assertThat(second.reused()).isFalse();assertThat(second.definition()).isNotEqualTo(first.definition());assertThat(requests).hasValue(2);assertThat(first.definition()).hasBinaryContent(body);}
 @Test void malformedPointerCannotEscapeProtectedRoot()throws Exception{var j=job("pointer");var first=run(j);Files.writeString(j.paths().cache().resolve("itemsparse-definition/current.properties"),"directory=../../outside\nsha256="+PinnedItemSparseDefinition.hash(body));assertThat(run(j).definition()).isNotEqualTo(first.definition());assertThat(requests).hasValue(2);}
 @Test void corruptCachedContentIsNotTrusted()throws Exception{var j=job("bytes");var first=run(j);Files.writeString(first.definition(),"corrupt");assertThat(run(j).reused()).isFalse();assertThat(requests).hasValue(2);}
 @Test void failedReplacementKeepsPreviousCompletePointerAndContent()throws Exception{var j=job("preserve");var first=run(j);Path pointer=j.paths().cache().resolve("itemsparse-definition/current.properties");byte[] previous=Files.readAllBytes(pointer);Files.writeString(first.evidence(),"provider=bad\n");status=503;assertThatThrownBy(()->run(j)).hasMessageContaining("HTTP 503");assertThat(pointer).hasBinaryContent(previous);assertThat(first.definition()).hasBinaryContent(body);}
 @Test void mismatchingContentAndRedirectAreRefused()throws Exception{var j=job("hash");assertThatThrownBy(()->reader("a".repeat(64),Duration.ofSeconds(2)).materialize(RaidbotsHotfixMaterializer.Permission.ALLOW_RAIDBOTS_HOTFIX,j,()->false,p->{})).hasMessageContaining("SHA-256");status=302;assertThatThrownBy(()->run(job("redirect"))).hasMessageContaining("HTTP 302");}
 @Test void parserRefusalDoesNotPublishEvenWhenHashMatches()throws Exception{body="different".getBytes(StandardCharsets.UTF_8);var j=job("parser");assertThatThrownBy(()->reader(PinnedItemSparseDefinition.hash(body),Duration.ofSeconds(2)).materialize(RaidbotsHotfixMaterializer.Permission.ALLOW_RAIDBOTS_HOTFIX,j,()->false,p->{})).hasMessageContaining("Invalid authored definition");assertThat(j.paths().cache().resolve("itemsparse-definition/current.properties")).doesNotExist();}
 @Test void cancelledDownloadAndOversizedResponseAreNotPublished()throws Exception{var j=job("cancel");AtomicBoolean cancel=new AtomicBoolean();assertThatThrownBy(()->reader().materialize(RaidbotsHotfixMaterializer.Permission.ALLOW_RAIDBOTS_HOTFIX,j,cancel::get,p->cancel.set(true))).isInstanceOf(CancellationException.class);assertThat(j.paths().cache().resolve("itemsparse-definition/current.properties")).doesNotExist();body=new byte[1_048_577];assertThatThrownBy(()->run(job("oversize"))).hasMessageContaining("byte limit");}
 @Test void stalledResponseTimesOutAndCannotPublish()throws Exception{server.removeContext("/schema");server.createContext("/schema",e->{e.sendResponseHeaders(200,1000);try{Thread.sleep(600);}catch(InterruptedException interrupted){Thread.currentThread().interrupt();}finally{e.close();}});var j=job("timeout");assertThatThrownBy(()->reader(PinnedItemSparseDefinition.hash(body),Duration.ofMillis(150)).materialize(RaidbotsHotfixMaterializer.Permission.ALLOW_RAIDBOTS_HOTFIX,j,()->false,p->{})).isInstanceOf(IOException.class);assertThat(j.paths().cache().resolve("itemsparse-definition/current.properties")).doesNotExist();}
}
